	@ParameterizedTest
	@EnumSource(value = FrontierFallbackReason.class, names = { "NO_GENERATION", "GENERATION_TOO_STALE",
			"CONFIDENCE_TOO_WIDE", "MEMORY_PRESSURE" })
	void authoritativeFrontierFallbackKeepsStorageSummaryAndExactCandidates(FrontierFallbackReason reason)
			throws Exception {
		StatementPattern pattern = pattern();
		lenient().when(cardinalities.estimateForPlanning(pattern)).thenReturn(STORAGE_ROWS);
		lenient().when(cardinalities.estimateExact(pattern)).thenReturn(STORAGE_ROWS);
		lenient().when(valueStore.getId(PREDICATE)).thenReturn(7L);
		lenient().when(statistics.estimateLeafCurrent(any(FrontierLeafProbe.class))).thenReturn(unavailable(reason));

		LmdbStorageEstimatorEvidence authoritative = authoritative(cardinalities);
		EstimateContext context = decisionExactContext(pattern);
		List<EstimateCandidate> candidates = authoritative.leafCandidates(pattern, context);

		assertEquals(1, candidates.size(), () -> "expected one storage-summary candidate, got " + kinds(candidates));
		EstimateCandidate summary = candidates.get(0);
		assertEquals(EstimateCandidate.Kind.STORAGE_SUMMARY, summary.kind());
		assertEquals(STORAGE_ROWS, summary.estimate().rows(), 0.0d);
		assertEquals(STORAGE_ROWS * 0.5d, summary.evidence().lowerBound(), 0.0d);
		assertEquals(STORAGE_ROWS * 2.0d, summary.evidence().upperBound(), 0.0d);
		assertTrue(summary.evidence().source().startsWith("lmdb-storage-summary"), summary.evidence().source());
		assertTrue(summary.evidence().source().contains(reason.name()),
				"the storage-summary source must record why Frontier declined: " + summary.evidence().source());

		EstimateCandidate exact = authoritative.exactCandidate(pattern, context).orElseThrow();
		assertEquals(EstimateCandidate.Kind.EXACT_STORAGE, exact.kind());
		assertEquals(STORAGE_ROWS, exact.estimate().rows(), 0.0d);

		BagEstimate resolved = new EstimateEvidenceResolver().resolveForDecision(candidates, context,
				() -> authoritative.exactCandidate(pattern, context).orElse(null));
		assertEquals(STORAGE_ROWS, resolved.rows(), 0.0d);
	}

