	@Test
	void authoritativeFrontierFallbackWithInvalidSummaryOffersTotalRowsCeiling() throws Exception {
		StatementPattern pattern = pattern();
		lenient().when(cardinalities.estimateForPlanning(argThat(candidate -> candidate != null
				&& candidate.getPredicateVar().hasValue()))).thenReturn(-1.0d);
		lenient().when(cardinalities.estimateForPlanning(argThat(candidate -> candidate != null
				&& !candidate.getSubjectVar().hasValue() && !candidate.getPredicateVar().hasValue()
				&& !candidate.getObjectVar().hasValue()))).thenReturn(TOTAL_ROWS);
		lenient().when(valueStore.getId(PREDICATE)).thenReturn(7L);
		lenient().when(statistics.estimateLeafCurrent(any(FrontierLeafProbe.class)))
				.thenReturn(unavailable(FrontierFallbackReason.GENERATION_TOO_STALE));

		LmdbStorageEstimatorEvidence authoritative = authoritative(cardinalities);
		EstimateContext context = EstimateContext.root(pattern, IDENTITY, 1L);
		List<EstimateCandidate> candidates = authoritative.leafCandidates(pattern, context);

		assertEquals(1, candidates.size(), () -> "expected one ceiling candidate, got " + kinds(candidates));
		EstimateCandidate ceiling = candidates.get(0);
		assertEquals(EstimateCandidate.Kind.HEURISTIC, ceiling.kind());
		assertEquals(TOTAL_ROWS, ceiling.estimate().rows(), 0.0d);
		assertEquals(0.0d, ceiling.evidence().lowerBound(), 0.0d);
		assertEquals(TOTAL_ROWS, ceiling.evidence().upperBound(), 0.0d);
		assertEquals("lmdb-unknown-ceiling", ceiling.evidence().source());

		BagEstimate resolved = new EstimateEvidenceResolver().resolve(candidates, context);
		assertEquals(TOTAL_ROWS, resolved.rows(), 0.0d);
		assertNotEquals(1.0d, resolved.rows(), 0.0d);
	}

	@Test
	void storageSummaryEvidenceResolvesAboveTheNoEvidenceHeuristic() throws Exception {
		StatementPattern pattern = pattern();
		lenient().when(cardinalities.estimateForPlanning(pattern)).thenReturn(STORAGE_ROWS);
		lenient().when(valueStore.getId(PREDICATE)).thenReturn(7L);
		lenient().when(statistics.estimateLeafCurrent(any(FrontierLeafProbe.class)))
				.thenReturn(unavailable(FrontierFallbackReason.CONFIDENCE_TOO_WIDE));

		LmdbStorageEstimatorEvidence authoritative = authoritative(cardinalities);
		EstimateContext context = snapshotOnlyContext(pattern);
		BagEstimate resolved = new EstimateEvidenceResolver()
				.resolve(authoritative.leafCandidates(pattern, context), context);

		assertEquals(STORAGE_ROWS, resolved.rows(), 0.0d);
		assertEquals(STORAGE_ROWS * 0.5d, resolved.metrics().get("optimizer.estimateLowerRows"), 0.0d);
		assertEquals(STORAGE_ROWS * 2.0d, resolved.metrics().get("optimizer.estimateUpperRows"), 0.0d);
		assertEquals(0.55d, resolved.metrics().get("optimizer.estimateConfidence"), 0.0d);
	}

	/**
	 * The only consumer of the packed leaf probe with a declined Frontier is the finite-binding lookup in
	 * {@link LmdbPackedCostModel}, which stamps its rows {@code DATABASE_EXACT}. The bounded B-tree page estimate is
	 * not exact, so the probe must decline (NaN) and let the general leaf path carry the STORAGE_SUMMARY evidence
	 * instead of certifying a sampled count, or a sampled zero, as exact.
	 */
	@Test
	void packedFiniteProbeDeclinesWhenFrontierDeclinesInsteadOfCertifyingPageEstimatesAsExact() throws Exception {
		lenient().when(valueStore.getId(PREDICATE)).thenReturn(7L);
		lenient().when(cardinalities.estimateForPlanningQualified(null, PREDICATE, null, null, 0))
				.thenReturn(LmdbPlanningCardinality.unqualified(LEGACY_PACKED_ROWS));
		lenient().when(statistics.estimateLeafCurrent(any(FrontierLeafProbe.class)))
				.thenReturn(unavailable(FrontierFallbackReason.NO_GENERATION));
		LmdbEstimatorStorageAccess access = new LmdbEstimatorStorageAccess(valueStore, null, cardinalities,
				() -> false, statistics, FrontierEstimatorMode.AUTHORITATIVE);

		double rows = access.packedStatementPatternRows(null, PREDICATE, null, null, 0);

		assertTrue(Double.isNaN(rows), "a declined Frontier probe must decline the finite lookup (NaN) rather than "
				+ "hand a bounded page estimate to a DATABASE_EXACT consumer, but was " + rows);
		verify(cardinalities, never()).estimateForPlanningQualified(null, PREDICATE, null, null, 0);
	}

	@Test
	void packedLeafWithUnresolvableConstantUsesLegacyRows() throws Exception {
		lenient().when(valueStore.getId(PREDICATE)).thenReturn(LmdbValue.UNKNOWN_ID);
		// the legacy packed route asks the storage source for a qualified estimate: an unknown term is an exact zero
		lenient().when(cardinalities.estimateForPlanningQualified(null, PREDICATE, null, null, 0))
				.thenReturn(LmdbPlanningCardinality.exact(0.0d, 0L));
		LmdbEstimatorStorageAccess access = new LmdbEstimatorStorageAccess(valueStore, null, cardinalities,
				() -> false, statistics, FrontierEstimatorMode.AUTHORITATIVE);

		double rows = access.packedStatementPatternRows(null, PREDICATE, null, null, 0);

		assertEquals(0.0d, rows, 0.0d, "an unresolvable constant is an exact zero, never NaN");
		verify(statistics, never()).estimateLeafCurrent(any(FrontierLeafProbe.class));
	}

